  async getPatientAccess(email = '') { const targetEmail = String(email || currentSession()?.email || '').trim().toLowerCase(); let cached = {}; try { cached = JSON.parse(localStorage.getItem(DB_KEY_PATIENT_ACCESS) || '{}'); } catch {} const fallback = normalizePatientAccess(cached[targetEmail], targetEmail); try { const records = (await rpc('app_list_videos', { p_token:token() }) || []).filter(isPatientAccessRecord); const current = records.find(record => { try { return String(JSON.parse(record.description || '{}').email || '').trim().toLowerCase() === targetEmail; } catch { return false; } }); const access = normalizePatientAccess(current || fallback, targetEmail); cached[targetEmail] = access; localStorage.setItem(DB_KEY_PATIENT_ACCESS, JSON.stringify(cached)); return access; } catch { return fallback; } },
