  async savePatientQuizLink(link) { const data = normalizePatientQuizLink({ ...link, id:link.id || `patient-quiz-${Date.now()}`, createdAt:link.createdAt || new Date().toISOString(), updatedAt:new Date().toISOString() }); if (!data.patientKey || !data.quizId) return { success:false, message:'Selecione um questionário.' }; const payload = { p_token:token(), p_title:`${data.patientName || 'Paciente'} — ${data.quizTitle}`, p_theme:PATIENT_QUIZ_LINK_THEME, p_description:JSON.stringify(data), p_url:`https://patient-quiz-link.local/${data.id}`, p_provider:'youtube', p_embed_url:`patient-quiz-link://${data.id}`, p_thumbnail_url:'' }; try { const records = (await rpc('app_list_videos', { p_token:token() }) || []).filter(isPatientQuizLinkRecord); const current = records.find(record => record.id === data.id || (() => { try { return JSON.parse(record.description || '{}').id === data.id; } catch { return false; } })()); const result = current ? await rpc('app_update_video', { ...payload, p_id:current.id }) : await rpc('app_add_video', payload); return { ...(result || {}), success:result?.success !== false, link:data }; } catch { const links = JSON.parse(localStorage.getItem(DB_KEY_PATIENT_QUIZ_LINKS) || '[]').map(normalizePatientQuizLink); const index = links.findIndex(item => item.id === data.id); if (index >= 0) links[index] = data; else links.push(data); localStorage.setItem(DB_KEY_PATIENT_QUIZ_LINKS, JSON.stringify(links)); return { success:true, link:data }; } },
