  async saveReminderSettings(reminders) { const normalized = normalizeReminders(reminders); localStorage.setItem(DB_KEY_REMINDERS, JSON.stringify(normalized)); const payloadBase = { p_token:token(), p_title:'Configurações de lembretes', p_theme:REMINDER_THEME, p_description:JSON.stringify(normalized), p_url:'https://reminder.local/settings', p_provider:'youtube', p_embed_url:'reminder://settings', p_thumbnail_url:'' }; try { const records = (await rpc('app_list_videos', { p_token:token() }) || []).filter(isReminderRecord); const record = records.sort((a, b) => new Date(b.updated_at || b.created_at || 0) - new Date(a.updated_at || a.created_at || 0))[0]; const result = record ? await rpc('app_update_video', { ...payloadBase, p_id:record.id }) : await rpc('app_add_video', payloadBase); return result || { success:true }; } catch { return { success:true, localOnly:true }; } },
  async getServices() { const local = JSON.parse(localStorage.getItem(DB_KEY_SERVICES) || '[]').map(normalizeService); let remote = []; try { remote = (await rpc('app_list_videos', { p_token: token() }) || []).filter(isServiceRecord).map(normalizeService); } catch {} const merged = [...remote]; local.forEach(service => { if (!merged.some(item => item.id === service.id)) merged.push(service); }); return merged.sort((a, b) => Number(b.active) - Number(a.active) || String(a.name).localeCompare(String(b.name), 'pt-BR')); },
  async addService(service) { const data = { name: (service.name || '').trim(), description: service.description || '', duration: Number(service.duration || 0), value: Number(service.value || 0), modality: service.modality || 'Presencial', active: service.active !== false }; if (!data.name) return { success: false, message: 'Informe o nome do serviço.' }; const payload = { p_token: token(), p_title: data.name, p_theme: data.active ? SERVICE_THEME : SERVICE_INACTIVE_THEME, p_description: encodeServiceContent(data.description, data), p_url: `https://service.local/${Date.now()}`, p_provider: 'youtube', p_embed_url: `service://${Date.now()}`, p_thumbnail_url: '' }; try { return await rpc('app_add_video', payload); } catch { const current = JSON.parse(localStorage.getItem(DB_KEY_SERVICES) || '[]'); const localService = { id: `local-service-${Date.now()}`, title: data.name, theme: data.active ? SERVICE_THEME : SERVICE_INACTIVE_THEME, description: encodeServiceContent(data.description, data), createdAt: new Date().toISOString() }; current.push(localService); localStorage.setItem(DB_KEY_SERVICES, JSON.stringify(current)); return { success: true, service: normalizeService(localService) }; } },
  async updateService(id, service) { const data = { name: (service.name || '').trim(), description: service.description || '', duration: Number(service.duration || 0), value: Number(service.value || 0), modality: service.modality || 'Presencial', active: service.active !== false }; if (!data.name) return { success: false, message: 'Informe o nome do serviço.' }; try { return await rpc('app_update_video', { p_token: token(), p_id: id, p_title: data.name, p_theme: data.active ? SERVICE_THEME : SERVICE_INACTIVE_THEME, p_description: encodeServiceContent(data.description, data), p_url: `https://service.local/${id}`, p_provider: 'youtube', p_embed_url: `service://${id}`, p_thumbnail_url: '' }); } catch { const current = JSON.parse(localStorage.getItem(DB_KEY_SERVICES) || '[]'); const index = current.findIndex(item => item.id === id); if (index < 0) return { success: false, message: 'Não foi possível localizar o serviço.' }; current[index] = { ...current[index], title: data.name, theme: data.active ? SERVICE_THEME : SERVICE_INACTIVE_THEME, description: encodeServiceContent(data.description, data), updatedAt: new Date().toISOString() }; localStorage.setItem(DB_KEY_SERVICES, JSON.stringify(current)); return { success: true, service: normalizeService(current[index]) }; } },
  async getPatientCalculators() { const local = JSON.parse(localStorage.getItem(DB_KEY_CALCULATORS) || '[]').map(normalizePatientCalculator); let remote = []; try { remote = (await rpc('app_list_videos', { p_token: token() }) || []).filter(isCalculatorRecord).map(normalizePatientCalculator); } catch {} const merged = [...remote]; local.forEach(calculator => { if (!merged.some(item => item.id === calculator.id)) merged.push(calculator); }); const byType = new Map(); merged.forEach((calculator, index) => { const current = byType.get(calculator.calculatorType); if (!current || calculatorVersionTime(calculator, index) >= calculatorVersionTime(current, index - 1)) byType.set(calculator.calculatorType, calculator); }); DEFAULT_PATIENT_CALCULATORS.map(normalizePatientCalculator).forEach(defaultCalculator => { if (!byType.has(defaultCalculator.calculatorType)) byType.set(defaultCalculator.calculatorType, defaultCalculator); }); return [...byType.values()].filter(calculator => calculator.state !== 'deleted'); },
